<script setup lang="ts">
import {computed} from 'vue';
import type {Handoff,ResultEvent} from './handoff-contract';
import {handoffCopy,handoffEventLabel} from './handoff-i18n';
const props=defineProps<{handoff:Handoff;lang:'zh'|'en';history?:boolean}>();
const t=computed(()=>handoffCopy[props.lang]);
const referenced=(id:string|undefined)=>props.handoff.result.history.find(e=>e.eventId===id);
const original=computed(()=>referenced(props.handoff.result.completion?.resultEventId));
const label=(e:ResultEvent)=>handoffEventLabel(e.type,props.lang);
</script>
<template><div class="handoff-facts"><p class="field-hint">{{t.revision}} {{handoff.revision}}</p><h4>{{t.request}}</h4><p class="preserve-text">{{handoff.request}}</p><h4>{{t.result}}</h4><p v-if="handoff.result.latestResult" class="preserve-text">{{handoff.result.latestResult.text}}</p><p v-else>{{t.none}}</p><p v-if="handoff.result.latestResult">{{t.actor}}: {{handoff.result.latestResult.actorId}} · {{t.at}}: {{handoff.result.latestResult.recordedAt}}</p><p class="handoff-completion-state"><strong>{{handoff.result.completion?t.complete:t.open}}</strong></p><template v-if="handoff.result.completion"><p>{{t.actor}}: {{handoff.result.completion.actorId}} · {{t.at}}: {{handoff.result.completion.recordedAt}}</p><h4>{{t.completionSource}} · {{handoff.result.completion.resultEventId}}</h4><p class="preserve-text completion-source-text">{{original?.text}}</p><p v-if="original?.eventId!==handoff.result.latestResult?.eventId" class="field-hint">{{t.later}}</p></template><p class="field-hint">{{t.boundary}}</p><section v-if="handoff.result.correctionRequests.length"><h4>{{t.requests}}</h4><article v-for="e in handoff.result.correctionRequests" :key="e.eventId"><p class="preserve-text">{{e.text}}</p><p>{{t.actor}}: {{e.actorId}} · {{t.at}}: {{e.recordedAt}} · {{t.target}}: {{e.targetEventId}}</p><p class="preserve-text">{{referenced(e.targetEventId)?.text}}</p></article></section><details v-if="history" :id="'handoff-history-'+handoff.id"><summary>{{t.history}}</summary><ol><li v-for="e in handoff.result.history" :key="e.eventId"><h4>{{label(e)}} · {{t.revision}} {{e.revision}}</h4><p>{{t.actor}}: {{e.actorId}} · {{t.at}}: {{e.recordedAt}}</p><p v-if="e.text" class="preserve-text">{{e.text}}</p><p v-if="e.reason" class="preserve-text">{{t.reason}}: {{e.reason}}</p><template v-if="e.targetEventId||e.resultEventId"><p>{{t.target}}: {{e.targetEventId||e.resultEventId}}</p><p class="preserve-text">{{referenced(e.targetEventId||e.resultEventId)?.text||referenced(referenced(e.targetEventId)?.resultEventId)?.text}}</p></template></li></ol></details></div></template>
